import { test, expect } from '@playwright/test';

test('product table looks right', async ({ page }) => {
  await page.goto('/products');
  await expect(page.getByRole('table')).toHaveScreenshot('products-table.png');
});

test('login form with tolerance', async ({ page }) => {
  await page.goto('/login');
  await expect(page.getByRole('main')).toHaveScreenshot('login.png', { maxDiffPixelRatio: 0.01 });
});
